const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const backlogId = String(body.backlog_id || body.selected_backlog_id || 'EN-AGENT-001').toUpperCase();
const depth = String(body.depth || body.refinement_depth || 'detallado').toLowerCase();
const dryRun = body.dry_run !== false;

const prompt = [
  `Refina ${backlogId} como DRAFT.`,
  `Nivel de detalle: ${depth}.`,
  'Usa project/backlog/templates/hu-template.yaml, project/kanban/board.yaml, project/agents-operating-model.md y .kiro/steering/project-governance.md.',
  'Produce HUs/tareas pequeñas y verificables con rol experto, rol revisor, criterios de aceptacion, DoR, DoD, evidencia esperada, riesgos, dependencias y si el trabajo es humano, agente o mixto.',
  'No modifiques HU congeladas. No marques nada como DONE. No apruebes compras, control fisico ni despliegues criticos.',
  'Si falta informacion, haz una sola pregunta.'
].join(' ');

return [{
  json: {
    agent: 'project-refinement',
    workspace: 'central',
    prompt,
    mode: 'draft',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'WF-REFINE-STORY-001',
      agent_id: 'AGENT-REF-001',
      backlog_id: backlogId,
      depth,
      requested_by: body.requested_by || 'chat-gateway'
    }
  }
}];
